 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    components = []
    unseen = set(occupied)
    while unseen:
        start = min(unseen)
        color = grid[start[0]][start[1]]
        stack = [start]
        unseen.remove(start)
        comp = {start}
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen and grid[p[0]][p[1]] == color:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        components.append((color, comp))

    # Pack every connected object to the right, settling rightmost objects first.
    components.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
    settled = set()
    positions = []
    for color, comp in components:
        current = set(comp)
        while True:
            moved = {(r, c+1) for r, c in current}
            if any(c >= w for _, c in moved) or moved & settled:
                break
            current = moved
        positions.append((color, current))
        settled.update(current)

    out = [[0] * w for _ in range(h)]
    for color, comp in positions:
        for r, c in comp:
            out[r][c] = color
    return out

